@[simp]
private theorem shiftRankEmbedding_val (t k : ℕ) (r : Fin t) :
    (shiftRankEmbedding t k r).1 = r.1 + k

private theorem gammaScale_mem_orderedSimplex {N k q : ℕ} (hq : 1 ≤ q)
    (z : Gamma N k) :
    gammaScale q z ∈ orderedSimplex k ((N : ℝ) / q)

private theorem gridGammaScale_mem_orderedSimplex {k D : ℕ} {L : ℝ}
    (hD : 1 ≤ D) (hL : 0 ≤ L) (z : Gamma ⌊(D : ℝ) * L⌋₊ k) :
    gammaScale D z ∈ orderedSimplex k L

theorem SimpleGraph.IsRankedCover.toGammaRankedCover {n k t : ℕ}
    (hk : k ≤ n) {centers : Fin t → Configuration (Fin n) k}
    (hcover : (pathTokenGraph n k).IsRankedCover centers) :
    IsGammaRankedCover (fun r ↦ configurationEquivGamma hk (centers r))

theorem IsGammaRankedCover.toPathTokenRankedCover {n k t : ℕ}
    (hk : k ≤ n) {centers : Fin t → Gamma (n - k) k}
    (hcover : IsGammaRankedCover centers) :
    (pathTokenGraph n k).IsRankedCover
      (fun r ↦ (configurationEquivGamma hk).symm (centers r))

theorem twoTokenBallRegion_ncard_le {N r : ℕ} {σ : ℤ} {c : ℤ × ℤ}
    (hc : c ∈ parityTriangle N σ) :
    (twoTokenBallRegion N σ c r).ncard ≤ (parityOffsetSquare r).ncard

theorem twoTokenBallRegion_ncard_le_quadratic {N r : ℕ} {σ : ℤ} {c : ℤ × ℤ}
    (hc : c ∈ parityTriangle N σ) :
    (twoTokenBallRegion N σ c r).ncard ≤ 2 * r ^ 2 + 2 * r + 1

theorem twoTokenBallRegion_ncard_eq_quadratic_of_fits {N r : ℕ} {σ : ℤ} {c : ℤ × ℤ}
    (hc : c ∈ parityTriangle N σ) (hfits : ParityOffsetSquareFits N σ c r) :
    (twoTokenBallRegion N σ c r).ncard = 2 * r ^ 2 + 2 * r + 1

theorem cubeCoverNumber_spec {k : ℕ} {L : ℝ}
    (h : ∃ q, 1 ≤ q ∧ HasCubeRankedCover k L q) :
    1 ≤ cubeCoverNumber k L ∧ HasCubeRankedCover k L (cubeCoverNumber k L)

theorem cubeCoverNumber_min {k q : ℕ} {L : ℝ}
    (hq : 1 ≤ q ∧ HasCubeRankedCover k L q) :
    cubeCoverNumber k L ≤ q

theorem simplexCoverNumber_min {k q : ℕ} {L : ℝ}
    (hq : 1 ≤ q ∧ HasSimplexRankedCover k L q) :
    simplexCoverNumber k L ≤ q

theorem cube_lower_of_shelfPotential_lower {w z E : ℝ}
    (hE : E ≤ shelfPotential w z) :
    (3 / 4) * E ≤ w ^ 3

theorem comp_sort_mem_orderedSimplex {k : ℕ} {L : ℝ}
    {x : Fin k → ℝ} (hx : x ∈ realCube k L) :
    x ∘ Tuple.sort x ∈ orderedSimplex k L

theorem HasSimplexRankedCover.toCubePermutationCover {k q : ℕ} {L : ℝ}
    (hq : 1 ≤ q) (hcover : HasSimplexRankedCover k L q) :
    HasCubeRankedCover k L (Nat.factorial k * q)

private theorem natCast_div_pathTokenScale_eq_rpow {k n : ℕ} (hn : 0 < n) :
    (n : ℝ) / pathTokenAsymptoticScale k n =
      (n : ℝ) ^ ((1 : ℝ) / (k + 1 : ℝ))

theorem tendsto_pathTokenCandidateSimplexSide_atTop {k : ℕ}
    (hk : 0 < k) {c : ℝ} (hc : 0 < c) :
    Tendsto (pathTokenCandidateSimplexSide k c) atTop atTop

theorem IsPathMetricRankedCover.isRankedCover_pathTokenGraph {n k t : ℕ}
    {centers : Fin t → Configuration (Fin n) k}
    (h : IsPathMetricRankedCover centers) :
    (pathTokenGraph n k).IsRankedCover centers

theorem pathTokenBurningNumber_le_blockUpperBound {n k s : ℕ}
    (hk : k ≤ n) (hs : 1 ≤ s) :
    pathTokenBurningNumber n k hk ≤ blockUpperBound n k s

private theorem l1ClosedBall_eq_preimage_add {k : ℕ} (c : Fin k → ℝ) (r : ℝ) :
    l1ClosedBall c r =
      (fun x : Fin k → ℝ ↦ -c + x) ⁻¹' l1ClosedBall 0 r

theorem realCube_pow_le_rankedBallVolumeSum {k q : ℕ} {L : ℝ}
    (hk : 1 ≤ k) (hq : 1 ≤ q) (hL : 0 ≤ L)
    {centers : Fin q → (Fin k → ℝ)}
    (hcover : IsL1NormalizedRankedCover (realCube k L) centers) :
    L ^ k ≤ ((2 : ℝ) ^ k / k.factorial) *
      ∑ i : Fin q, ((i.1 : ℝ) / q) ^ k

theorem cubeNormalizedRankedCover_ratio_lower {k q : ℕ} {L : ℝ}
    (hk : 2 ≤ k) (hL : 0 < L) (hq : 1 ≤ q)
    {centers : Fin q → (Fin k → ℝ)}
    (hcover : IsL1NormalizedRankedCover (realCube k L) centers) :
    ((k.factorial : ℝ) * (k + 1)) / (2 : ℝ) ^ k ≤
      (q : ℝ) / L ^ k

private theorem rankPaddingValue_lt {q₀ q : ℕ} (hq₀ : 1 ≤ q₀) (hqq₀ : q₀ ≤ q)
    (j : Fin q₀) :
    rankPaddingValue q₀ q j.1 < q

theorem cubeCoverDensityAt_le_simplexCoverDensityAt {k : ℕ} {L : ℝ}
    (hk : 1 ≤ k) (hL : 0 < L) :
    cubeCoverDensityAt k L ≤ simplexCoverDensityAt k L

theorem cubeBulkDensity_le_simplexCoverDensityAt {k : ℕ} {L : ℝ}
    (hk : 1 ≤ k) (hL : 0 < L) :
    cubeBulkDensity k ≤ simplexCoverDensityAt k L

theorem twoTokenCubicThreshold_min {N t : ℕ}
    (h : 1 ≤ t ∧ N ≤ t * (2 * t ^ 2 + 1) / 3) :
    twoTokenCubicThreshold N ≤ t

theorem pathConfigurationDist_triangle {n k : ℕ}
    (A B C : Configuration (Fin n) k) :
    pathConfigurationDist A C ≤ pathConfigurationDist A B + pathConfigurationDist B C

theorem pathConfigurationDist_eq_zero_iff {n k : ℕ}
    (A B : Configuration (Fin n) k) :
    pathConfigurationDist A B = 0 ↔ A = B

theorem hasPathMetricRankedCover_blockUpperBound {n k s : ℕ}
    (hk : k ≤ n) (hs : 1 ≤ s) :
    HasPathMetricRankedCover n k (blockUpperBound n k s)

theorem parityCapApex_mem {h z : ℕ} {σ : ℤ}
    (hσ : (h + z : ℕ) ≡ σ [ZMOD 2]) :
    parityCapApex h z ∈ parityCap h z σ

theorem mem_residual_parityCap {h z a : ℕ} {σ : ℤ} {p : ℤ × ℤ}
    (ha : 2 * a ≤ z) (hp : p ∈ parityCap h z σ) (hY : (h + 2 * a : ℕ) ≤ p.2) :
    p ∈ parityCap (h + 2 * a) (z - 2 * a) σ

theorem pathTokenGraph_dist_eq_pathConfigurationDist {n k : ℕ}
    (A B : Configuration (Fin n) k) :
    (pathTokenGraph n k).dist A B = pathConfigurationDist A B

theorem pathTokenGraph_edist_eq_pathConfigurationDist {n k : ℕ}
    (A B : Configuration (Fin n) k) :
    (pathTokenGraph n k).edist A B = (pathConfigurationDist A B : ℕ∞)

private theorem sum_intCoordinate (r : ℕ) (f : ℕ → ℕ) :
    ∑ x : IntCoordinate r, f x.1.natAbs =
      f 0 + 2 * ∑ n ∈ Finset.range r, f (n + 1)

private theorem latticeBallPolynomial_succ_dim (k r : ℕ) :
    latticeBallPolynomial (k + 1) r =
      latticeBallPolynomial k r + 2 * rankedVolumePolynomial k r

private theorem card_missingParam {k N C : ℕ} (p : Fin k) :
    Fintype.card (MissingParam p N C) =
      (N + 1) ^ (k - 1) * (C + 1)

private theorem card_wallParam {k N C : ℕ} (hk : 1 ≤ k) :
    Fintype.card (WallParam k N C hk) =
      k * (N + 1) ^ (k - 1) * (C + 1)

private theorem translatedCellCenter_legal {k p q : ℕ}
    {ell L : ℝ} (hell : 0 ≤ ell) (hpL : (p : ℝ) * ell ≤ L)
    {baseCenters : Fin q → (Fin k → ℝ)}
    (hbaseLegal : ∀ j, baseCenters j ∈ realCube k ell)
    (a : StrictCell k p) (r : Fin q) :
    translatedCellCenter ell baseCenters a r ∈ orderedSimplex k L

private theorem translatedCellCenter_covers {k p q : ℕ}
    {ell : ℝ} {baseCenters : Fin q → (Fin k → ℝ)}
    (hbaseCover :
      ∀ y ∈ realCube k ell, ∃ j : Fin q,
        realL1Dist y (baseCenters j) ≤ (j.1 : ℝ) / q)
    (a : StrictCell k p) {x : Fin k → ℝ}
    (hx : x ∈ cellRegion ell a) :
    ∃ j : Fin q,
      realL1Dist x (translatedCellCenter ell baseCenters a j) ≤
        (j.1 : ℝ) / q

private theorem shiftedRank_normalized_le {I R : ℕ}
    (hI : 1 ≤ I) (r : Fin I) :
    (r.1 : ℝ) / I ≤ ((R + r.1 : ℕ) : ℝ) / (R + I)

private theorem wallMeshScale_pos {k : ℕ} {θ : ℝ}
    (hk : 1 ≤ k) (hθ : 0 < θ) :
    1 ≤ wallMeshScale k θ

private theorem wallMesh_error_le {k : ℕ} {θ : ℝ}
    (hk : 1 ≤ k) (hθ : 0 < θ) :
    (k : ℝ) / wallMeshScale k θ ≤ θ / 4

private theorem reserveRanks_cast_le {I : ℕ} {θ : ℝ}
    (hθ : 0 ≤ θ) :
    (reserveRanks θ I : ℝ) ≤ θ * I + 1

private theorem symmDiff_pair_eq_insert_erase {A : Finset V} {u v : V}
    (hu : u ∈ A) (hv : v ∉ A) :
    A ∆ ({u, v} : Finset V) = insert v (A.erase u)

theorem realL1Dist_clampToCube_le {k : ℕ} {L : ℝ}
    (x c : Fin k → ℝ) (hx : x ∈ realCube k L) :
    realL1Dist x (clampToCube L c) ≤ realL1Dist x c

@[simp]
private theorem splitLast_fst (k : ℕ) (x : Fin (k + 1) → ℝ) :
    (splitLast k x).1 = x (Fin.last k)

@[simp]
private theorem splitLast_snd (k : ℕ) (x : Fin (k + 1) → ℝ) (i : Fin k) :
    (splitLast k x).2 i = x i.castSucc

@[simp]
private theorem splitLast_symm_last (k : ℕ) (p : ℝ × (Fin k → ℝ)) :
    (splitLast k).symm p (Fin.last k) = p.1

private theorem splitLast_image_orderedSimplex (k : ℕ) (L : ℝ) :
    splitLast k '' orderedSimplex (k + 1) L =
      {p : ℝ × (Fin k → ℝ) |
        p.1 ∈ Set.Icc (0 : ℝ) L ∧ p.2 ∈ orderedSimplex k p.1}

theorem exists_cubeCoverDensityAt_lt {k : ℕ} {U : ℝ}
    (hU : cubeBulkDensity k < U) :
    ∃ L : ℝ, 0 < L ∧ cubeCoverDensityAt k L < U

theorem pathConfigurationDist_eq_one_of_adj {n k : ℕ}
    (A B : Configuration (Fin n) k) (h : (pathTokenGraph n k).Adj A B) :
    pathConfigurationDist A B = 1

theorem pathConfigurationDist_le_walk_length {n k : ℕ}
    {A B : Configuration (Fin n) k} (p : (pathTokenGraph n k).Walk A B) :
    pathConfigurationDist A B ≤ p.length

theorem pathToken_closedBall_subset_pathConfigurationBall {n k : ℕ}
    (C : Configuration (Fin n) k) (r : ℕ) :
    (pathTokenGraph n k).closedBall C r ⊆ pathConfigurationBall C r

theorem pathToken_closedBall_ncard_le {n k : ℕ}
    (C : Configuration (Fin n) k) (r : ℕ) :
    ((pathTokenGraph n k).closedBall C r).ncard ≤ latticeBallPolynomial k r

theorem twoToken_closedBall_ncard_le {n : ℕ}
    (C : Configuration (Fin n) 2) (r : ℕ) :
    ((pathTokenGraph n 2).closedBall C r).ncard ≤ 2 * r ^ 2 + 2 * r + 1

@[simp]
private theorem highRadiusEmbedding_val (R M : ℕ) (i : Fin M) :
    (highRadiusEmbedding R M i).val = R + i.val

private theorem finOrderEmbedding_shift_le {n k : ℕ} (hk : k ≤ n)
    (f : Fin k ↪o Fin n) (i : Fin k) :
    (f i).val - i.val ≤ n - k

theorem nonempty_configuration_of_le (V : Type*) [Fintype V] {k : ℕ}
    (hk : k ≤ Fintype.card V) :
    Nonempty (Configuration V k)

theorem pathConfigurationDisplacement_mem_latticeBall {n k r : ℕ}
    {C A : Configuration (Fin n) k} (hA : A ∈ pathConfigurationBall C r) :
    pathConfigurationDisplacement C A ∈ latticeBall k r

theorem pathConfigurationDisplacement_injective {n k : ℕ}
    (C : Configuration (Fin n) k) :
    Function.Injective (pathConfigurationDisplacement C)

theorem pathConfigurationBall_ncard_le {n k : ℕ}
    (C : Configuration (Fin n) k) (r : ℕ) :
    (pathConfigurationBall C r).ncard ≤ latticeBallPolynomial k r

theorem IsRankedCover.extendLength [Nonempty V] {G : SimpleGraph V} {s t : ℕ}
    {centers : Fin s → V} (h : G.IsRankedCover centers) (hst : s ≤ t) :
    ∃ fullCenters : Fin t → V, G.IsRankedCover fullCenters

theorem isChronologicalCover_iff_isRankedCover {G : SimpleGraph V} {t : ℕ}
    {sources : Fin t → V} :
    G.IsChronologicalCover sources ↔ G.IsRankedCover (chronologicalToRanked sources)

theorem ShelfRun.exists_rankedCover {m : ℕ} {h z w q : ℕ → ℕ}
    (run : ShelfRun m h z w q) {σ : ℤ}
    (hσ : (h 0 + z 0 : ℕ) ≡ σ [ZMOD 2]) :
    ∃ centers : Fin (w 0) → ℤ × ℤ,
      IsParityCapRankedCover (h 0) (z 0) (w 0) σ centers

theorem ShelfRun.w_le_initial {m : ℕ} {h z w q : ℕ → ℕ}
    (run : ShelfRun m h z w q) {i : ℕ} (hi : i ≤ m) :
    w i ≤ w 0

theorem ShelfRun.three_mul_w_le_four_mul_w_next {m : ℕ}
    {h z w q : ℕ → ℕ} (run : ShelfRun m h z w q) {i : ℕ} (hi : i < m) :
    3 * w i ≤ 4 * w (i + 1)

theorem ShelfRun.z_sub_z_next {m : ℕ} {h z w q : ℕ → ℕ}
    (run : ShelfRun m h z w q) {i : ℕ} (hi : i < m) :
    (z i : ℝ) - z (i + 1) = 2 * (w (i + 1) : ℝ)

theorem ShelfRun.nonterminal_count_mul_le {m : ℕ}
    {h z w q : ℕ → ℕ} (run : ShelfRun m h z w q) {B : ℝ}
    (hB : ∀ i < m, B ≤ (w i : ℝ)) :
    (m : ℝ) * ((3 / 2 : ℝ) * B) ≤ (z 0 : ℝ)

theorem ShelfRun.nonterminal_count_le_ceil {m : ℕ}
    {h z w q : ℕ → ℕ} (run : ShelfRun m h z w q) {B : ℝ}
    (hBpos : 0 < B) (hB : ∀ i < m, B ≤ (w i : ℝ)) :
    m ≤ ⌈(2 * (z 0 : ℝ)) / (3 * B)⌉₊

theorem ShelfRun.shelf_count_le_ceil_add_one {m : ℕ}
    {h z w q : ℕ → ℕ} (run : ShelfRun m h z w q) {B : ℝ}
    (hBpos : 0 < B) (hB : ∀ i < m, B ≤ (w i : ℝ)) :
    m + 1 ≤ ⌈(2 * (z 0 : ℝ)) / (3 * B)⌉₊ + 1

private theorem shelfBeta_widthScale_cube {ε : ℝ} (hε : 0 < ε) (N : ℕ) :
    (shelfBeta ε * shelfWidthScale N) ^ 3 =
      (3 / 4 : ℝ) * (shelfDelta ε / 2 * (N : ℝ) ^ 2)

theorem IsLeastShelfWidth.minimality_lower {w z q : ℕ}
    (hq : IsLeastShelfWidth w z q) (hz : w - 1 < z) :
    (q - 1) * (w - q + 1) < z

private theorem natDist_le_pred_of_div_eq {a b s : ℕ} (hs : 1 ≤ s)
    (hdiv : a / s = b / s) :
    Nat.dist a b ≤ s - 1
